import{_ as s,C as i,o as d,c as l,j as t,a,E as n,a2 as o}from"./chunks/framework.sc8Z_ZE3.js";const v=JSON.parse('{"title":"Network and Git","description":"","frontmatter":{},"headers":[],"relativePath":"security/network.md","filePath":"security/network.md"}'),h={name:"security/network.md"};function c(u,e,p,m,f,g){const r=i("Badge");return d(),l("div",null,[e[2]||(e[2]=t("h1",{id:"network-and-git",tabindex:"-1"},[a("Network and Git "),t("a",{class:"header-anchor",href:"#network-and-git","aria-label":'Permalink to "Network and Git"'},"​")],-1)),n(r,{type:"built",text:"Built"}),e[3]||(e[3]=o(' What Octryx AI may reach, and how it talks to Git.<h2 id="outbound-addresses" tabindex="-1">Outbound addresses <a class="header-anchor" href="#outbound-addresses" aria-label="Permalink to &quot;Outbound addresses&quot;">​</a></h2><p>Every outbound call names its connection type, and the type alone decides where it may go. An unknown type is refused; a call without a type gets the strictest rule, public addresses only.</p><ul><li><strong>Tools hosted on the internet</strong> (Jira and Confluence Cloud, GitHub, GitLab, Bitbucket, ServiceNow and similar): public addresses only. An on-premises instance on a private address is reachable only through the <strong>private hosts</strong> list of its type, which a platform admin keeps, entry by entry, as exact host and port.</li><li><strong>Systems in your private network</strong> (Kubernetes, Grafana, Vault, Argo CD and similar): private addresses are fine.</li><li><strong>Never</strong>: the platform&#39;s own pod-local addresses and cloud metadata addresses.</li><li>A custom REST API and an outbound webhook receiver follow the rule for tools on the internet.</li></ul><h2 id="git-never-asks" tabindex="-1">Git never asks <a class="header-anchor" href="#git-never-asks" aria-label="Permalink to &quot;Git never asks&quot;">​</a></h2>',5)),t("p",null,[e[0]||(e[0]=a("Octryx AI runs Git without a terminal: it never waits for a password prompt. Credentials come only from the connection. Over HTTPS the token travels in a header set through the environment, never in the command line, the URL or a file, and never in a log. ",-1)),n(r,{type:"progress",text:"Building"}),e[1]||(e[1]=a(" One exception is being fixed: when Octryx AI sets up a new repository, the token is still written into the remote URL.",-1))]),e[4]||(e[4]=o('<h2 id="credentials-stay-on-the-server" tabindex="-1">Credentials stay on the server <a class="header-anchor" href="#credentials-stay-on-the-server" aria-label="Permalink to &quot;Credentials stay on the server&quot;">​</a></h2><p>During a run, the developer&#39;s machine holds no Jira or Git host credential. Pushing, opening pull requests and updating tickets happen on the server. On the machine, <code>git push</code>, <code>gh</code>, <code>glab</code>, <code>hub</code>, <code>jira</code>, <code>acli</code> and <code>bb</code>, uploads such as <code>scp</code> or <code>curl -d</code>, and reading credential files are refused.</p><p>In a phase where the agent has a free shell, these rules are a guardrail, not a wall: the developer&#39;s own credentials are on their own machine.</p><h2 id="the-launcher-s-folders" tabindex="-1">The launcher&#39;s folders <a class="header-anchor" href="#the-launcher-s-folders" aria-label="Permalink to &quot;The launcher&#39;s folders&quot;">​</a></h2><p>A device runs jobs only in folders on its allow list. Adding a folder asks for a confirmation on the device itself (<code>--yes</code> answers it in advance): widening is possible only there, never from the platform. See <a href="/docs/install/launcher">Launcher and devices</a>.</p>',5))])}const y=s(h,[["render",c]]);export{v as __pageData,y as default};
